template:
use std::thread;

fn spawn_value<T: ⟦slot1⟧ + 'static>(val: T) -> thread::JoinHandle<T> {
    thread::spawn(move || val)
}
fn spawn_ref<T: ⟦slot2⟧ + 'static>(val: &'static T) -> thread::JoinHandle<()> {
    thread::spawn(move || { let _ref = val; })
}

fn main() {
    let handle = spawn_value(String::from("hi"));
    assert_eq!(handle.join().unwrap(), "hi");
    static NUM: i32 = 42;
    spawn_ref(&NUM).join().unwrap();
}

